using System;
using System.Collections.Generic;

namespace PaperTrails.Core
{
    // Artist-supplied arena shapes, baked from SVG at 80x80 (1 bit per
    // cell, row-major). Regenerate with svg_raster.py; do not hand-edit.
    public static class ArenaMasks
    {
        static readonly Dictionary<ArenaKind,string> Svg = new Dictionary<ArenaKind,string>{
            {ArenaKind.Diamond, ""},
            {ArenaKind.LightningBolt, ""},
            {ArenaKind.Mustache, ""},
            {ArenaKind.Flare, ""},
            {ArenaKind.Cash, ""},
            {ArenaKind.Tilda, ""},
            {ArenaKind.Triangle, ""},
            {ArenaKind.Circle, ""},
            {ArenaKind.Square, ""},
            {ArenaKind.Parallelogram, ""},
            {ArenaKind.CoolS, ""},
            {ArenaKind.CubicCurve, ""},
        };
        public static bool TryGet(ArenaKind kind,bool[] mask)
        {
            string b64;
            if(!Svg.TryGetValue(kind,out b64))return false;
            byte[] bytes=Convert.FromBase64String(b64);
            if(bytes.Length*8<mask.Length)return false;
            for(int i=0;i<mask.Length;i++)mask[i]=(bytes[i/8]&(1<<(i%8)))!=0;
            return true;
        }
    }
}
